// ScriptStruct CoreUObject.Vector2D
// 0x0008 (0x0008 - 0x0000)
struct FVector2D
{
public:
    float X;
    float Y;

public:
    FVector2D() : X(0), Y(0) {}
    FVector2D(float v) : X(v), Y(v) {}
    FVector2D(float x, float y) : X(x), Y(y) {}
    
public:
    
    static const FVector2D ZeroVector;
    static const FVector2D UnitVector;

    FVector2D& operator*=(const FVector2D& Other)
    {
        *this = *this * Other;
        return *this;
    }

    FVector2D& operator*=(float Scalar)
    {
        *this = *this * Scalar;
        return *this;
    }

    FVector2D& operator+=(const FVector2D& Other)
    {
        *this = *this + Other;
        return *this;
    }

    FVector2D& operator-=(const FVector2D& Other)
    {
        *this = *this - Other;
        return *this;
    }

    FVector2D& operator/=(const FVector2D& Other)
    {
        *this = *this / Other;
        return *this;
    }

    FVector2D& operator/=(float Scalar)
    {
        *this = *this / Scalar;
        return *this;
    }

    float GetDistanceTo(const FVector2D& Other) const
    {
        FVector2D DiffVector = Other - *this;
        return DiffVector.Magnitude();
    }

    static float GetDistance(const FVector2D& A, const FVector2D& B)
    {
        return A.GetDistanceTo(B);
    }

    float GetDistanceToInMeters(const FVector2D& Other) const
    {
        return GetDistanceTo(Other) * 0.01;
    }

    FVector2D GetNormalized() const
    {
        return *this / Magnitude();
    }

    bool IsZero() const
    {
        return X == 0.0 && Y == 0.0;
    }

    float Magnitude() const
    {
        return FMath::Sqrt((X * X) + (Y * Y));
    }
    
    float SizeSquared() const
    {
        return X*X + Y*Y;
    }

    bool operator!=(const FVector2D& Other) const
    {
        return X != Other.X || Y != Other.Y;
    }

    FVector2D operator*(const FVector2D& Other) const
    {
        return {X * Other.X, Y * Other.Y};
    }

    FVector2D operator*(float Scalar) const
    {
        return {X * Scalar, Y * Scalar};
    }

    FVector2D operator+(const FVector2D& Other) const
    {
        return {X + Other.X, Y + Other.Y};
    }

    FVector2D operator-(const FVector2D& Other) const
    {
        return {X - Other.X, Y - Other.Y};
    }

    FVector2D operator/(const FVector2D& Other) const
    {
        return {X / Other.X, Y / Other.Y};
    }

    FVector2D operator/(float Scalar) const
    {
        return {X / Scalar, Y / Scalar};
    }

    bool operator==(const FVector2D& Other) const
    {
        return X == Other.X && Y == Other.Y;
    }

    FVector2D AppendY(float _Y)  const
    {
        return FVector2D(X, this->Y + _Y);
    }

    FVector2D AppendX(float _X)  const
    {
        return FVector2D(this->X + _X, Y);
    }
};

