// ScriptStruct CoreUObject.Rotator
// 0x000C (0x000C - 0x0000)
struct FRotator
{
public:
    float Pitch;
    float Yaw;
    float Roll;
    
public:
    FRotator() = default;
    FRotator(float _Pitch, float _Yaw, float _Roll = 0.0f) : Pitch(_Pitch), Yaw(_Yaw), Roll(_Roll) {}
    
public:
    /** A zero rotator (0,0,0) */
    static const FRotator ZeroRotator;

    FVector Vector() const
    {
        float CP, SP, CY, SY;
        FMath::SinCos( &SP, &CP, FMath::DegreesToRadians(Pitch) );
        FMath::SinCos( &SY, &CY, FMath::DegreesToRadians(Yaw) );
        FVector V = FVector( CP*CY, CP*SY, SP );

        return V;
    }

    FMatrix ToMatrix() const
    {
        float CP, SP, CY, SY, CR, SR;
        FMath::SinCos( &SP, &CP, FMath::DegreesToRadians(Pitch) );
        FMath::SinCos( &SY, &CY, FMath::DegreesToRadians(Yaw) );
        FMath::SinCos( &SR, &CR, FMath::DegreesToRadians(Roll) );

        FMatrix RotationMatrix;

        RotationMatrix.M[0][0] = CP * CY;
        RotationMatrix.M[0][1] = CP * SY;
        RotationMatrix.M[0][2] = SP;
        RotationMatrix.M[0][3] = 0.f;

        RotationMatrix.M[1][0] = SR * SP * CY - CR * SY;
        RotationMatrix.M[1][1] = SR * SP * SY + CR * CY;
        RotationMatrix.M[1][2] = -SR * CP;
        RotationMatrix.M[1][3] = 0.f;

        RotationMatrix.M[2][0] = -(CR * SP * CY + SR * SY);
        RotationMatrix.M[2][1] = CY * SR - CR * SP * SY;
        RotationMatrix.M[2][2] = CR * CP;
        RotationMatrix.M[2][3] = 0.f;

        RotationMatrix.M[3][0] = 0.f;
        RotationMatrix.M[3][1] = 0.f;
        RotationMatrix.M[3][2] = 0.f;
        RotationMatrix.M[3][3] = 1.f;

        return RotationMatrix;
    }

    FQuat ToQuaterion() const
    {
        const float DEG_TO_RAD = PI/(180.f);
        const float RADS_DIVIDED_BY_2 = DEG_TO_RAD/2.f;
        float SP, SY, SR;
        float CP, CY, CR;

        const float PitchNoWinding = FMath::Fmod(Pitch, 360.0f);
        const float YawNoWinding = FMath::Fmod(Yaw, 360.0f);
        const float RollNoWinding = FMath::Fmod(Roll, 360.0f);

        FMath::SinCos(&SP, &CP, PitchNoWinding * RADS_DIVIDED_BY_2);
        FMath::SinCos(&SY, &CY, YawNoWinding * RADS_DIVIDED_BY_2);
        FMath::SinCos(&SR, &CR, RollNoWinding * RADS_DIVIDED_BY_2);

        FQuat RotationQuat;
        RotationQuat.X =  CR*SP*SY - SR*CP*CY;
        RotationQuat.Y = -CR*SP*CY - SR*CP*SY;
        RotationQuat.Z =  CR*CP*SY - SR*SP*CY;
        RotationQuat.W =  CR*CP*CY + SR*SP*SY;
        return RotationQuat;
    }
    
    static float ClampAxis( float Angle )
    {
        // returns Angle in the range (-360,360)
        Angle = FMath::Fmod(Angle, 360.f);

        if (Angle < 0.f)
        {
            // shift to [0,360) range
            Angle += 360.f;
        }

        return Angle;
    }

    static float NormalizeAxis( float Angle )
    {
        // returns Angle in the range [0,360)
        Angle = ClampAxis(Angle);

        if (Angle > 180.f)
        {
            // shift to (-180,180]
            Angle -= 360.f;
        }

        return Angle;
    }
};
